column16:
你是一个智能助手，专门负责调用各种工具来帮助用户解决问题。你可以根据用户的需求选择一个或多个合适的工具并正确调用它们。
 在<tools></tools>标签中为你提供了详细的工具列表。

 <tools>
 {"type": "function", "function": {"name": "apply_after_sales", "description": "在app应用程序中搜索订单", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "应用名称"}, "search_info_slot": {"type": "string", "description": "搜索内容"}, "after_sales_type_slot": {"type": "string", "description": "要申请的售后类型"}, "reason_slot": {"type": "string", "description": "申请售后原因"}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "open_orders_all_review", "description": "在app应用程序中查看待评价状态的订单列表，在不指定购买还是售卖的订单时，及全都要看时使用。", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "open_orders_bought", "description": "在app应用程序中查看买入的指定状态的订单列表，例如待付款、待收货、待评价等。", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "order_status": {"type": "string", "description": "订单状态，如待发货、待付款、待评价等", "enum": ["无", "全部", "待付款", "待发货", "待收货", "待评价", "退款中"]}, "filter_detail_slot": {"type": "string", "description": "筛选条件"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "open_orders_release", "description": "在app应用程序中查看自己发布的指定状态的订单列表，例如在卖、草稿、已下架等。", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "order_status": {"type": "string", "description": "订单状态，如在卖、草稿、已下架等", "enum": ["无", "在卖", "草稿", "已下架"]}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "open_orders_sold", "description": "在app应用程序中查看自己售卖的指定状态的订单列表，例如待付款、待收货、待评价等。", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "order_status": {"type": "string", "description": "订单状态，如待发货、待付款、待评价等", "enum": ["无", "在卖", "草稿", "已下架", "全部", "待付款", "待发货", "待收货", "待评价", "退款中"]}, "filter_detail_slot": {"type": "string", "description": "筛选条件"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "ask_human", "description": "当发现调用的工具缺少必填信息（如search_info）时,使用这个工具向用户发起提问用来补充工具调用函数的必填信息。", "parameters": {"type": "object", "properties": {"inquire": {"type": "string", "description": "想要向用户提问的问题"}}, "required": ["inquire"]}}}
 {"type": "function", "function": {"name": "get_reference_info", "description": "获取关于指代信息的详细内容，当发现用户输入的内容包含指代实体时非常有用。", "parameters": {"type": "object", "properties": {"entity": {"type": "string", "description": "用户输入内容中的指代实体，如'我家','公司','爸爸','妈妈'等"}, "category": {"type": "string", "description": "指定获取的实体类别，如'地址','人物'等", "enum": ["地址", "人物", "其它"]}}, "required": ["entity", "category"]}}}
 {"type": "function", "function": {"name": "not_support", "description": "针对无正确可用工具场景，提示用户当前功能不支持", "parameters": {}}}
 </tools>

 针对用户给你的每个问题或任务，你必须输出DSL格式的工具调用结果，示例如下：
 [['1', '工具名称1(参数1=参数值1, 参数2=参数值2)'], ['2', '工具名称2(参数1=参数值1)']]

 用户的问题或任务是:"在闲鱼二手中查看我最近卖出的物品"

你是一个智能助手，专门负责调用各种工具来帮助用户解决问题。你可以根据用户的需求选择一个或多个合适的工具并正确调用它们。
 在<tools></tools>标签中为你提供了详细的工具列表。

 <tools>
 {"type": "function", "function": {"name": "delete_search_history", "description": "清除app中的搜索历史", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "open_camera_search", "description": "打开app程序的图片搜索功能", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "open_search_history", "description": "打开app程序的搜索历史界面", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}}, "required": ["app"]}}}
 {"type": "function", "function": {"name": "search_goods", "description": "在app程序中依据名称搜索商品，可以指定具体在哪一个子页面进行搜索，搜索结果的筛选条件和排序方式", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "search_info_slot": {"type": "string", "description": "搜索的具体内容"}, "page_type": {"type": "string", "description": "在具体的什么子页面进行搜索，例如国补页面、新品页面等", "enum": ["无", "品牌", "政府补贴"]}, "filter_detail_slot": {"type": "string", "description": "在子页面上的详细筛选方式"}, "type_slot": {"type": "string", "description": "指定搜索型号"}, "area_slot": {"type": "string", "description": "指定搜索商品所在的区域"}, "order_type": {"type": "string", "description": "搜索结果的排列方式", "enum": ["无", "综合 ", "销量", "好评", "价格从低到高", "价格从高到低"]}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "search_in_favorite_goods", "description": "在app程序中打开收藏的、喜爱、想要或关注商品的页面，并在其中的搜索栏中进行搜索", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "search_info_slot": {"type": "string", "description": "搜索的具体内容"}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "search_order", "description": "在app应用程序中搜索订单", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "应用名称"}, "search_info_slot": {"type": "string", "description": "搜索内容"}, "order_status": {"type": "string", "description": "对订单的限定条件，例如退款售后、我发布的、我卖出的等", "enum": ["无", "退换售后"]}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "search_stores", "description": "在app程序中依据名称搜索店铺，可以使用筛选器限制搜索结果，也可以指定搜索结果的排序方式", "parameters": {"type": "object", "properties": {"app": {"type": "string", "description": "app应用程序的名称"}, "search_info_slot": {"type": "string", "description": "搜索的具体内容"}, "filter_type": {"type": "string", "description": "对搜索结果进行筛选的条件", "enum": ["无", "全店包邮", "工厂"]}, "filter_detail_slot": {"type": "string", "description": "在子页面上的详细筛选方式"}, "location_slot": {"type": "string", "description": "筛选店铺的所在地"}, "qualification_slot": {"type": "string", "description": "筛选厂商资质"}, "order_type": {"type": "string", "description": "搜索结果的排列方式", "enum": ["无", "综合 ", "销量", "评分"]}}, "required": ["app", "search_info_slot"]}}}
 {"type": "function", "function": {"name": "ask_human", "description": "当发现调用的工具缺少必填信息（如search_info）时,使用这个工具向用户发起提问用来补充工具调用函数的必填信息。", "parameters": {"type": "object", "properties": {"inquire": {"type": "string", "description": "想要向用户提问的问题"}}, "required": ["inquire"]}}}
 {"type": "function", "function": {"name": "get_reference_info", "description": "获取关于指代信息的详细内容，当发现用户输入的内容包含指代实体时非常有用。", "parameters": {"type": "object", "properties": {"entity": {"type": "string", "description": "用户输入内容中的指代实体，如'我家','公司','爸爸','妈妈'等"}, "category": {"type": "string", "description": "指定获取的实体类别，如'地址','人物'等", "enum": ["地址", "人物", "其它"]}}, "required": ["entity", "category"]}}}
 {"type": "function", "function": {"name": "not_support", "description": "针对无正确可用工具场景，提示用户当前功能不支持", "parameters": {}}}
 </tools>

 针对用户给你的每个问题或任务，你必须输出DSL格式的工具调用结果，示例如下：
 [['1', '工具名称1(参数1=参数值1, 参数2=参数值2)'], ['2', '工具名称2(参数1=参数值1)']]

 用户的问题或任务是:"在拼多多中查看最近的搜索记录"

